#!/usr/bin/env node
// pi-9router-sync — sync active 9router models into ~/.pi/agent/models.json
// Dipanggil oleh systemd user unit pi-9router-sync.service (generated by pi-9router-restore).
// Portable: semua path relatif ke $HOME, tidak ada secret di file ini.
const fs = require('fs');
const path = require('path');
const http = require('http');

const HOME = process.env.HOME || require('os').homedir();
const initSqlJs = require(path.join(HOME, '.9router/runtime/node_modules/sql.js'));

const dbPath = path.join(HOME, '.9router/db/data.sqlite');
const secretPath = path.join(HOME, '.9router/auth/cli-secret');
const modelsPath = path.join(HOME, '.pi/agent/models.json');
const extraModelsPath = path.join(HOME, '.9router/pi-extra-models.json');

const providerPrefixMap = {
  'gemini-cli': ['gc'],
  'antigravity': ['ag'],
  'anthropic': ['anthropic'],
  'openai': ['openai'],
  'blackbox': ['blackbox'],
  'alicode': ['alicode'],
  'alicode-intl': ['alicode-intl'],
  'byteplus': ['byteplus'],
  'copilot': ['copilot'],
  'deepseek': ['deepseek'],
  'groq': ['groq'],
  'openrouter': ['openrouter'],
  'vertex': ['vertex'],
  'gemini': ['gemini'],
};

function readJson(file, fallback) {
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return fallback; }
}

function fetchModels(apiKey) {
  return new Promise((resolve, reject) => {
    const req = http.get({
      hostname: 'localhost',
      port: 20128,
      path: '/v1/models',
      headers: { Authorization: `Bearer ${apiKey}` }
    }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 400) {
          return reject(new Error(`9router /v1/models returned ${res.statusCode}: ${data.slice(0, 300)}`));
        }
        try {
          resolve(JSON.parse(data));
        } catch (err) {
          reject(err);
        }
      });
    });
    req.on('error', reject);
  });
}

async function getActiveProviders() {
  const SQL = await initSqlJs({
    locateFile: file => path.join(HOME, '.9router/runtime/node_modules/sql.js/dist', file)
  });
  const db = new SQL.Database(fs.readFileSync(dbPath));
  const res = db.exec("select provider from providerConnections where isActive = 1 order by provider");
  return (res[0]?.values || []).map(v => v[0]);
}

function modelMeta(id) {
  const isGemini = /gemini/i.test(id);
  const reasoning = /gemini-2\.5-pro|gemini-3/i.test(id) || undefined;
  return {
    id,
    ...(reasoning ? { reasoning: true } : {}),
    ...(isGemini ? { input: ['text', 'image'] } : {}),
    name: id.replace(/\//g, '__')
  };
}

async function main() {
  if (!fs.existsSync(dbPath)) {
    throw new Error('9router is not installed or initialized');
  }

  // 9router 0.5.x tak lagi menulis auth/cli-secret; endpoint lokal 20128 tak cek Authorization.
  const apiKey = fs.existsSync(secretPath)
    ? fs.readFileSync(secretPath, 'utf8').trim()
    : 'noauth';
  const activeProviders = await getActiveProviders();
  const payload = await fetchModels(apiKey);
  const ids = (payload.data || []).map(m => m.id).sort();

  const allowedPrefixes = new Set();
  for (const provider of activeProviders) {
    (providerPrefixMap[provider] || [provider]).forEach(prefix => allowedPrefixes.add(prefix));
  }

  const selectedModels = ids
    .filter(id => {
      const prefix = id.includes('/') ? id.split('/')[0] : id;
      return allowedPrefixes.has(prefix);
    })
    .map(modelMeta);

  // Pinned models: bisa di-chat via 9router tapi tidak muncul di /v1/models
  // (free/opencode routing). Lihat ~/.9router/pi-extra-models.json.
  const extras = readJson(extraModelsPath, { models: [] }).models || [];
  const seen = new Set(selectedModels.map(m => m.id));
  for (const extra of extras) {
    if (extra && extra.id && !seen.has(extra.id)) {
      selectedModels.push(extra);
      seen.add(extra.id);
    }
  }

  const cfg = readJson(modelsPath, { providers: {} });
  if (!cfg.providers) cfg.providers = {};
  cfg.providers['9router'] = {
    baseUrl: 'http://localhost:20128/v1',
    api: 'openai-completions',
    apiKey,
    compat: {
      supportsDeveloperRole: false,
      supportsReasoningEffort: false,
      maxTokensField: 'max_tokens'
    },
    models: selectedModels
  };

  fs.mkdirSync(path.dirname(modelsPath), { recursive: true });
  fs.writeFileSync(modelsPath, JSON.stringify(cfg, null, 2) + '\n');
  console.log(JSON.stringify({ activeProviders, modelCount: selectedModels.length }, null, 2));
}

main().catch(err => {
  console.error(err.message || String(err));
  process.exit(1);
});
